<?php require 'inc.php'; head('Artesanos');$A=rows('SELECT a.*,(SELECT COUNT(*) FROM productos WHERE artesano_id=a.id AND activo=1) n FROM artesanos a');?>
<h1>Nuestros artesanos</h1><p class="mut">Cada tienda es administrada por su propio creador desde su panel.</p><div class="grid" style="margin-top:20px"><?php foreach($A as $a):?><div class="card"><div style="font-size:40px">🧑‍🎨</div><h3><?=e($a['nombre'])?></h3><div style="color:var(--teal)"><?=e($a['estado'])?></div><p class="mut"><?=e($a['descripcion'])?></p><b><?=$a['n']?> productos</b></div><?php endforeach;?></div><?php foot();
